Subject: [PATCH] kcm: only show the power button setting when there is a power
 button

The power button row was always shown because the KCM hardcoded the
button as present, which confused users on devices without one. Check
whether any input device can send the power key and hide it otherwise.

BUG: 488115
---
 kcm/CMakeLists.txt |  1 +
 kcm/PowerKCM.cpp   | 45 ++++++++++++++++++++++++++++++++++++++++++++-
 2 files changed, 45 insertions(+), 1 deletion(-)

diff --git a/kcm/CMakeLists.txt b/kcm/CMakeLists.txt
index 4b04fc032..46baa3a24 100644
--- a/kcm/CMakeLists.txt
+++ b/kcm/CMakeLists.txt
@@ -20,4 +20,5 @@ target_link_libraries(kcm_powerdevilprofilesconfig
     KF6::ItemModels
     KF6::Solid
     powerdevilcore
+    ${UDEV_LIBS}
 )
diff --git a/kcm/PowerKCM.cpp b/kcm/PowerKCM.cpp
index f9450ee4f..9e5238e6d 100644
--- a/kcm/PowerKCM.cpp
+++ b/kcm/PowerKCM.cpp
@@ -40,6 +40,9 @@
 #include <QQuickItem>
 #include <QQuickRenderControl>

+#include <libudev.h>
+#include <linux/input-event-codes.h>
+
 // TODO Plasma 7: Change kcm_powerdevilprofilesconfig to kcm_powerdevil
 K_PLUGIN_FACTORY_WITH_JSON(PowerDevilProfilesConfigFactory, "kcm_powerdevilprofilesconfig.json", {
     registerPlugin<PowerDevil::PowerKCM>();
@@ -48,6 +51,46 @@ K_PLUGIN_FACTORY_WITH_JSON(PowerDevilProfilesConfigFactory, "kcm_powerdevilprofi

 using namespace Qt::StringLiterals;

+namespace
+{
+bool hasPowerKey()
+{
+    struct udev *udev = udev_new();
+    if (!udev) {
+        return true;
+    }
+
+    bool found = false;
+    struct udev_enumerate *enumerate = udev_enumerate_new(udev);
+    udev_enumerate_add_match_subsystem(enumerate, "input");
+    udev_enumerate_add_match_property(enumerate, "ID_INPUT_KEY", "1");
+    udev_enumerate_scan_devices(enumerate);
+
+    struct udev_list_entry *entry;
+    udev_list_entry_foreach(entry, udev_enumerate_get_list_entry(enumerate))
+    {
+        struct udev_device *device = udev_device_new_from_syspath(udev, udev_list_entry_get_name(entry));
+        if (!device) {
+            continue;
+        }
+        // The key bitmap is a list of hex words, most significant first
+        const QStringList words = QString::fromLatin1(udev_device_get_sysattr_value(device, "capabilities/key")).split(u' ', Qt::SkipEmptyParts);
+        udev_device_unref(device);
+
+        constexpr int bitsPerWord = sizeof(long) * 8;
+        const int index = words.size() - 1 - KEY_POWER / bitsPerWord;
+        if (index >= 0 && (words.at(index).toULongLong(nullptr, 16) >> (KEY_POWER % bitsPerWord)) & 1) {
+            found = true;
+            break;
+        }
+    }
+
+    udev_enumerate_unref(enumerate);
+    udev_unref(udev);
+    return found;
+}
+}
+
 namespace PowerDevil
 {

@@ -233,7 +276,7 @@ void PowerKCM::load()
     m_externalServiceSettings->load(renderWindowAsKAuthParent);

     setLidPresent(LidController().isLidPresent());
-    setPowerButtonPresent(true /* HACK This needs proper API to determine! */);
+    setPowerButtonPresent(hasPowerKey());

     KQuickManagedConfigModule::load();
 }
